/bin/zsh -lc "python3 -B - <<'PY'
import json
import tempfile
from pathlib import Path
from unittest.mock import patch
import settings

with tempfile.TemporaryDirectory(dir='.') as directory:
    root = Path(directory)
    target = root / 'settings.json'
    data = {'text': '안녕하세요 café 😀', 'items': [1, True, None]}
    for initial in (None, b'old settings\\n'):
        if initial is not None:
            target.write_bytes(initial)
        assert settings.save_settings(target, data) is None
        raw = target.read_bytes()
        assert json.loads(raw.decode('utf-8')) == data
        assert '안녕하세요'.encode('utf-8') in raw
        assert list(root.iterdir()) == [target]
        target.unlink()
    for existing in (False, True):
        for failure in ('serialization', 'replacement', 'encoding'):
            old = b'original bytes\\n'
            if existing:
                target.write_bytes(old)
            try:
                if failure == 'serialization':
                    settings.save_settings(target, {'partial': 1, 'invalid': object()})
                elif failure == 'encoding':
                    settings.save_settings(target, {'invalid': '\\ud800'})
                else:
                    error = OSError('replacement failed')
                    with patch.object(settings.os, 'replace', side_effect=error):
                        settings.save_settings(target, data)
            except (TypeError, UnicodeEncodeError, OSError) as caught:
                if failure == 'replacement':
                    assert caught is error
            else:
                raise AssertionError(f'{failure} did not propagate')
            assert target.read_bytes() == old if existing else not target.exists()
            assert set(root.iterdir()) == ({target} if existing else set())
            if existing:
                target.unlink()
print('Passed: new/existing UTF-8 saves; serialization, encoding, and replacement failures; original preservation and temporary cleanup.')
